/// <summary>
/// Constructs a new METSupplierChangeCompletedBusinessEvent business event.
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <param name = "_vendAccount">Vendor account</param>
/// <param name = "_coverageWareHouseIdList">List of coverage warehouse list</param>
/// <returns>A new <c>METSupplierChangeCompletedBusinessEvent</c> business event.</returns>
public static METSupplierChangeCompletedBusinessEvent newFromSupplierChangeCompleted(ItemId _itemId, List _coverageWhsIdVendAccountNumberList)
{
    METSupplierChangeCompletedBusinessEvent event = new METSupplierChangeCompletedBusinessEvent();

    event.parmItemId(_itemId);
    event.parmCoverageWhsIdVendAccountNumberList(_coverageWhsIdVendAccountNumberList); //C - Task 259910: CB409 - PE-128: D365 to PIM

    return event;
}

/// <summary>
/// Get or set coverage whs id and vendor account
/// Task 259910: CB409 - PE-128: D365 to PIM
/// </summary>
/// <param name = "coverageWhsIdVendAccountNumberList">Vendor account</param>
/// <returns>Coverage whs id and vendor account list</returns>
public List parmCoverageWhsIdVendAccountNumberList(List _coverageWhsIdVendAccountNumberList = coverageWhsIdVendAccountNumberList)
{
    coverageWhsIdVendAccountNumberList = _coverageWhsIdVendAccountNumberList;

    return coverageWhsIdVendAccountNumberList;
}

/// <summary>
/// Get or set Item id
/// </summary>
/// <param name = "_itemId">Item Id</param>
/// <returns>ItemId</returns>
private ItemId parmItemId(ItemId _itemId = itemId)
{
    itemId = _itemId;

    return itemId;
}

/// <summary>
/// Overrides to provide Supplier change completed data.
/// </summary>
/// <returns>The <c>METSupplierChangeCompletedBusinessEventContract</c> of the event.</returns>
public BusinessEventsContract buildContract()
{
    return METSupplierChangeCompletedBusinessEventContract::newFromSupplierChangeCompleted(itemId, coverageWhsIdVendAccountNumberList);
}

/// <summary>
/// creates new object
/// </summary>
private void new()
{
}
